import re

## 기존 카드번호 탐지 함수 ##
def make_old_card_pattern(bins, card_len):
    trailing_map = {
        16: r'[-\s]?\d{2}[-\s]?\d{4}[-\s]?\d{4}',
        15: r'[-\s]?\d{2}[-\s]?\d{4}[-\s]?\d{3}',
        14: r'[-\s]?\d{2}[-\s]?\d{4}[-\s]?\d{2}',
    }

    trailing = trailing_map[card_len]

    bin4_groups = {}

    for b in bins:
        k = b[:4]
        bin4_groups.setdefault(k, []).append(b[4:])

    parts = []

    for b4, suffixes in bin4_groups.items():
        suf_pat = '|'.join(sorted(set(suffixes)))
        parts.append(rf'{b4}[-\s]?(?:{suf_pat})')

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat}){trailing}(?!\d)'
    )

## 새로운 카드번호 탐지 함수 ##
def make_fixed_card_pattern(bins, card_len):
    parts = []

    for bin_code in bins:
        # BIN이 숫자로만 이루어졌는지 확인
        if not bin_code.isdigit():
            continue

        # BIN 길이에 따라 남은 카드번호 길이 계산
        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN 부분
        # 기존 코드처럼 앞 4자리 뒤에 공백/하이픈 허용
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # BIN 뒤에 남아야 할 숫자 개수
        trailing = rf'(?:[-\s]?\d){{{remaining_len}}}'

        parts.append(
            rf'{bin_pattern}{trailing}'
        )

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )
 
## 길이 계산 검증 패턴 ##
'''1단계: BIN 길이에 따른 카드 전체 길이 처리'''
def make_length_fixed_pattern(bins, card_len):
    parts = []

    for bin_code in bins:

        # 숫자로 된 BIN만 사용
        if not bin_code.isdigit():
            continue

        # BIN 뒤에 남아야 하는 숫자 개수 계산
        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # 이번 단계에서는 구분자를 생각하지 않음
        pattern = rf'{bin_code}\d{{{remaining_len}}}'

        parts.append(pattern)

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )

'''2단계: BIN 내부 4자리 경계의 구분자 처리'''
def make_bin_separator_pattern(bins, card_len):
    parts = []

    for bin_code in bins:

        if not bin_code.isdigit():
            continue

        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN을 앞 4자리와 나머지로 분리
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        # 앞 4자리와 나머지 사이에
        # 하이픈 또는 공백을 0~1개 허용
        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # 아직 BIN 뒤쪽 구분자는 처리하지 않음
        pattern = rf'{bin_pattern}\d{{{remaining_len}}}'

        parts.append(pattern)

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )

'''3단계: 16자리 카드의 전체 구분자 처리'''
def make_16digit_separator_pattern(bins):
    parts = []

    card_len = 16

    for bin_code in bins:

        if not bin_code.isdigit():
            continue

        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN 부분
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # 8자리 BIN인 경우
        # 남은 8자리 = 4자리 + 4자리
        if remaining_len == 8:
            trailing = r'[-\s]?\d{4}[-\s]?\d{4}'

        # 6자리 BIN인 경우는 일단 다음 단계에서 처리
        else:
            trailing = rf'\d{{{remaining_len}}}'

        parts.append(
            rf'{bin_pattern}{trailing}'
        )

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )

'''4단계: 16자리 카드 - 6자리/8자리 BIN 처리'''
def make_16digit_separator_pattern(bins):
    parts = []

    card_len = 16

    for bin_code in bins:

        if not bin_code.isdigit():
            continue

        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN 내부 구분자
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # 6자리 BIN → 뒤에 10자리
        if remaining_len == 10:
            trailing = r'[-\s]?\d{2}[-\s]?\d{4}[-\s]?\d{4}'

        # 8자리 BIN → 뒤에 8자리
        elif remaining_len == 8:
            trailing = r'[-\s]?\d{4}[-\s]?\d{4}'

        else:
            continue

        parts.append(
            rf'{bin_pattern}{trailing}'
        )

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )

'''5단계: AMEX 15자리 - 6자리/8자리 BIN 처리'''
def make_amex_pattern(bins):
    parts = []
    card_len = 15

    for bin_code in bins:

        if not bin_code.isdigit():
            continue

        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN 내부: 첫 4자리 뒤 구분자 허용
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # 6자리 BIN → 9자리 남음
        # 기존 코드 구조 유지
        if remaining_len == 9:
            trailing = r'[-\s]?\d{2}[-\s]?\d{4}[-\s]?\d{3}'

        # 8자리 BIN → 7자리 남음
        elif remaining_len == 7:
            trailing = r'[-\s]?\d{2}[-\s]?\d{5}'

        else:
            continue

        parts.append(
            rf'{bin_pattern}{trailing}'
        )

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )

'''6단계: DINERS 14자리 처리'''
def make_diners_pattern(bins):
    parts = []
    card_len = 14

    for bin_code in bins:

        if not bin_code.isdigit():
            continue

        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN 내부 구분자
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # 6자리 BIN → 8자리 남음
        if remaining_len == 8:
            trailing = r'[-\s]?\d{2}[-\s]?\d{4}[-\s]?\d{2}'

        else:
            continue

        parts.append(
            rf'{bin_pattern}{trailing}'
        )

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )

'''7단계: 최종 통합 후보'''
def make_final_card_pattern(bins, card_len):
    parts = []

    for bin_code in bins:

        if not bin_code.isdigit():
            continue

        remaining_len = card_len - len(bin_code)

        if remaining_len <= 0:
            continue

        # BIN 내부 구분자 처리
        b4 = bin_code[:4]
        suffix = bin_code[4:]

        bin_pattern = rf'{b4}[-\s]?{suffix}'

        # -------------------------
        # 16자리 카드
        # -------------------------
        if card_len == 16:

            # 6자리 BIN → 10자리 남음
            if remaining_len == 10:
                trailing = (
                    r'[-\s]?\d{2}'
                    r'[-\s]?\d{4}'
                    r'[-\s]?\d{4}'
                )

            # 8자리 BIN → 8자리 남음
            elif remaining_len == 8:
                trailing = (
                    r'[-\s]?\d{4}'
                    r'[-\s]?\d{4}'
                )

            else:
                continue

        # -------------------------
        # 15자리 카드
        # -------------------------
        elif card_len == 15:

            # 6자리 BIN → 9자리 남음
            if remaining_len == 9:
                trailing = (
                    r'[-\s]?\d{2}'
                    r'[-\s]?\d{4}'
                    r'[-\s]?\d{3}'
                )

            # 8자리 BIN → 7자리 남음
            elif remaining_len == 7:
                trailing = (
                    r'[-\s]?\d{2}'
                    r'[-\s]?\d{5}'
                )

            else:
                continue

        # -------------------------
        # 14자리 카드
        # -------------------------
        elif card_len == 14:

            # 6자리 BIN → 8자리 남음
            if remaining_len == 8:
                trailing = (
                    r'[-\s]?\d{2}'
                    r'[-\s]?\d{4}'
                    r'[-\s]?\d{2}'
                )

            else:
                continue

        else:
            continue

        parts.append(
            rf'{bin_pattern}{trailing}'
        )

    # 중복 제거
    parts = list(dict.fromkeys(parts))

    if not parts:
        return re.compile(r'(?!x)x')

    bin_pat = '|'.join(parts)

    return re.compile(
        rf'(?<!\d)(?:{bin_pat})(?!\d)'
    )
