for name, bins in BIN_GROUPS.items():

    print(f"\n[{name}]")

    # BIN 길이별 개수
    lengths = Counter(len(b) for b in bins)

    print("총 BIN 개수:", len(bins))
    print("길이별 개수:", dict(sorted(lengths.items())))

    # 숫자가 아닌 BIN
    non_digit = [
        b for b in bins
        if not b.isdigit()
    ]

    # 현재 함수가 처리하지 못하는 길이
    unsupported = [
        b for b in bins
        if len(b) not in (6, 8)
    ]

    # 중복 BIN
    duplicates = [
        b for b, count in Counter(bins).items()
        if count > 1
    ]

    print("숫자 아닌 BIN:", non_digit)
    print("6/8자리 외 BIN:", unsupported)
    print("중복 BIN:", duplicates)